using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Book of Exalted Deeds (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class BookOfExaltedDeeds2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("book-of-exalted-deeds", null, 0, MagicItemType.WondrousItem, ItemRarity.Artifact, true, ContentSource.RealmForge,
			null,
			("Libro delle imprese eroiche", "Oggetto meraviglioso, artefatto (richiede sintonia con una creatura di allineamento buono)",
			"Il leggendario trattato su tutto ciò che di buono esiste nel multiverso, importante per molte religioni. Non è la scrittura di una fede in particolare: i suoi autori vi hanno raccolto la loro visione della vera virtù e consigli per sconfiggere il male. Il libro non resta a lungo nello stesso luogo: appena letto, svanisce verso un altro angolo del multiverso dove la sua guida possa portare luce. I tentativi di copiarlo non ne catturano mai la magia.\n\nUn pesante fermaglio a forma di ali d'angelo lo tiene chiuso, e solo una creatura buona in sintonia con esso può aprirlo. Una volta aperto, la creatura deve passare 80 ore a leggerlo e studiarlo per ottenerne i benefici; altri possono leggerne il testo, ma senza coglierne il significato né i benefici. Una creatura malvagia che tenta di leggerlo subisce 24d6 danni radiosi, che ignorano resistenze e immunità e non possono essere ridotti né evitati; se ne viene ridotta a 0 punti ferita, scompare in un lampo accecante e viene distrutta, lasciando dietro di sé i suoi averi.\n\nI benefici durano solo finché il personaggio si impegna a fare il bene: se non compie almeno un atto di gentilezza o generosità ogni 10 giorni, o se compie volontariamente un atto malvagio, li perde tutti.\n\n***Proprietà casuali.*** 2 proprietà benefiche minori e 2 proprietà benefiche maggiori.\n\n***Saggezza aumentata.*** Dopo lo studio, il punteggio di Saggezza del personaggio aumenta di 2, fino a un massimo di 24. Il libro non può concedere questo beneficio più di una volta.\n\n***Magia illuminata.*** Dopo lo studio, ogni slot incantesimo che il personaggio spende per lanciare un incantesimo da chierico o da paladino conta come uno slot di un livello superiore.\n\n***Aureola.*** Dopo lo studio, il personaggio ottiene un'aureola protettiva che emette luce intensa in un raggio di 3 metri e luce fioca per altri 3 metri, e che può far apparire o sparire con un'azione bonus. Finché è presente, il personaggio dispone di vantaggio alle prove di Carisma (Persuasione) con le creature buone e di Carisma (Intimidire) con quelle malvagie, e gli immondi e i non morti nella luce intensa dell'aureola subiscono svantaggio ai tiri per colpire contro di lui.\n\n***Distruggere il libro.*** Si dice che non possa essere distrutto finché nel multiverso esiste il bene. Annegarlo nel Fiume Stige, però, ne cancella scritte e immagini e lo rende inerte per 1d100 anni.", null),
			("Book of Exalted Deeds", "Wondrous item, artifact (requires attunement by a creature of good alignment)",
			"The legendary treatise on everything good in the multiverse, important to many religions. It isn't the scripture of a single faith: its authors gathered in it their vision of true virtue and advice for defeating evil. The book never stays long in one place: once read, it vanishes to another corner of the multiverse where its guidance can bring light. Attempts to copy it never capture its magic.\n\nA heavy clasp shaped like angel wings keeps it shut, and only a good creature attuned to it can open it. Once it is open, the creature must spend 80 hours reading and studying it to gain its benefits; others can read the text but grasp neither its meaning nor its benefits. An evil creature that tries to read it takes 24d6 radiant damage, which ignores resistance and immunity and can't be reduced or avoided; a creature reduced to 0 hit points by it vanishes in a blinding flash and is destroyed, leaving its belongings behind.\n\nThe benefits last only as long as you strive to do good: if you don't perform at least one act of kindness or generosity every 10 days, or if you willingly do evil, you lose all of them.\n\n***Random Properties.*** 2 minor beneficial properties and 2 major beneficial properties.\n\n***Increased Wisdom.*** After the study, your Wisdom score increases by 2, to a maximum of 24. The book can't grant this benefit more than once.\n\n***Enlightened Magic.*** After the study, any spell slot you expend to cast a cleric or paladin spell counts as a slot one level higher.\n\n***Halo.*** After the study, you gain a protective halo that sheds bright light in a 10-foot radius and dim light for another 10 feet; you can make it appear or vanish as a bonus action. While it is present, you have advantage on Charisma (Persuasion) checks with good creatures and Charisma (Intimidation) checks with evil ones, and fiends and undead in its bright light have disadvantage on attack rolls against you.\n\n***Destroying the Book.*** It is said it can't be destroyed while good exists in the multiverse. Drowning it in the River Styx, however, wipes its words and images and leaves it powerless for 1d100 years.", null));
	}
}
